"use client";

import { useRef } from "react";
import { useRouter } from "next/navigation";
import { motion } from "motion/react";
import { FileAudio, Mic, Square, X } from "@/components/common/icons";
import { DostOrb } from "@/components/orb/DostOrb";
import { useLongTranscribe } from "@/hooks/useLongTranscribe";
import { useRecorder } from "@/hooks/useRecorder";
import { LANGUAGES } from "@/lib/i18n/languages";
import type { Shop } from "@/lib/types";

/** Synthetic noisy customer voice orders generated by scripts/make_fixtures.py (Timbre + mixed shop noise). */
export const SAMPLE_ORDERS = [
  { file: "/fixtures/samples/order-hi-noisy.wav", label: "हिन्दी · shor ke saath", flag: "🔊" },
  { file: "/fixtures/samples/order-kn-noisy.wav", label: "ಕನ್ನಡ · noisy", flag: "🔊" },
  { file: "/fixtures/samples/order-ta.wav", label: "தமிழ்", flag: "🎧" },
  { file: "/fixtures/samples/order-hinglish-long.wav", label: "Hinglish · lamba order", flag: "⏱️" },
];

const STAGE_TEXT: Record<string, string> = {
  decoding: "Audio khol raha hoon…",
  transcribing: "Sun raha hoon",
  understanding: "Order samajh raha hoon…",
  saving: "Packing list bana raha hoon…",
};

export function NewOrderSheet({ shop, onClose }: { shop: Shop; onClose: () => void }) {
  const router = useRouter();
  const fileRef = useRef<HTMLInputElement>(null);
  const { progress, run, reset } = useLongTranscribe(shop);
  const recorder = useRecorder({ maxSec: 120, onAutoStop: (r) => void go(r.samples) });
  const busy = !["idle", "error", "done"].includes(progress.stage);

  const go = async (input: Blob | Float32Array) => {
    const id = await run(input);
    if (id) {
      onClose();
      router.push(`/orders/${id}`);
    }
  };

  const sample = async (file: string) => {
    try {
      const res = await fetch(file);
      if (!res.ok) throw new Error();
      await go(await res.blob());
    } catch {
      reset();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center" role="dialog" aria-modal="true" aria-label="New voice order">
      <button type="button" aria-label="Close" className="absolute inset-0 bg-black/40" onClick={busy ? undefined : onClose} />
      <motion.div
        initial={{ y: "100%" }}
        animate={{ y: 0 }}
        transition={{ type: "spring", stiffness: 320, damping: 32 }}
        className="relative z-10 max-h-[92dvh] w-full max-w-lg overflow-y-auto rounded-t-[32px] bg-bg px-4 pb-8 pt-3"
      >
        <div className="mx-auto mb-3 h-1.5 w-12 rounded-full bg-line" />
        <div className="mb-2 flex items-center justify-between">
          <h2 className="text-xl font-semibold">Naya voice order</h2>
          {!busy && (
            <button type="button" onClick={onClose} aria-label="Close" className="rounded-full p-2 text-muted">
              <X className="h-6 w-6" />
            </button>
          )}
        </div>
        <p className="mb-4 text-sm text-muted">Customer ka WhatsApp voice note daalein — kisi bhi bhasha mein, shor ho tab bhi.</p>

        {busy || progress.stage === "error" ? (
          <div className="flex flex-col items-center py-4 text-center">
            <DostOrb state={progress.stage === "error" ? "sad" : "thinking"} size={110} />
            <p className="mt-3 text-lg font-semibold">
              {progress.stage === "error" ? progress.error : STAGE_TEXT[progress.stage]}
              {progress.stage === "transcribing" && progress.chunks > 1 && ` (${progress.chunk}/${progress.chunks})`}
            </p>
            {progress.language && <span className="mt-1 rounded-full bg-indigo-soft px-3 py-0.5 text-sm font-semibold text-indigo">{LANGUAGES[progress.language].nativeName}</span>}
            {progress.transcript && <p className="mt-3 max-h-32 overflow-y-auto rounded-2xl bg-card px-4 py-3 text-left text-sm">“{progress.transcript}”</p>}
            {progress.stage === "error" && (
              <button type="button" onClick={reset} className="mt-4 rounded-full bg-brand px-5 py-3 font-semibold text-brand-ink shadow-card">
                Dobara try karein
              </button>
            )}
          </div>
        ) : recorder.status === "recording" ? (
          <div className="flex flex-col items-center py-4">
            <DostOrb state="listening" level={recorder.level} size={120} />
            <p className="tabular mt-2 font-semibold text-muted">{Math.floor(recorder.elapsed)}s / 120s</p>
            <button
              type="button"
              onClick={async () => {
                const r = await recorder.stop();
                if (r) await go(r.samples);
              }}
              className="mt-3 flex min-h-12 items-center gap-2 rounded-full bg-chili px-6 font-semibold text-white shadow-card"
            >
              <Square className="h-4 w-4 fill-current" /> Done
            </button>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={() => fileRef.current?.click()}
                className="flex min-h-28 flex-col items-center justify-center gap-2 rounded-card border border-line bg-card font-semibold shadow-card"
              >
                <FileAudio className="h-8 w-8 text-indigo" /> Audio file
              </button>
              <button
                type="button"
                onClick={() => void recorder.start()}
                className="flex min-h-28 flex-col items-center justify-center gap-2 rounded-card border border-line bg-card font-semibold shadow-card"
              >
                <Mic className="h-8 w-8 text-brand-strong" /> Record
              </button>
            </div>
            <input
              ref={fileRef}
              type="file"
              accept="audio/*,.opus,.ogg,.m4a,.mp3,.wav,.aac"
              className="hidden"
              onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) void go(f);
                e.target.value = "";
              }}
            />
            <h3 className="mb-2 mt-5 text-sm font-semibold uppercase tracking-wide text-muted">Sample try karein</h3>
            <div className="grid gap-2">
              {SAMPLE_ORDERS.map((s) => (
                <button
                  key={s.file}
                  type="button"
                  onClick={() => void sample(s.file)}
                  className="flex min-h-12 items-center gap-3 rounded-2xl border border-line bg-card px-4 text-left font-semibold"
                >
                  <span aria-hidden>{s.flag}</span> {s.label}
                </button>
              ))}
            </div>
          </>
        )}
      </motion.div>
    </div>
  );
}
